{
  "css": ".itinerary { display: flex; flex-direction: column; gap: 40px; }
.itinerary h2 { font-size: 16px; line-height: 22px; font-weight: 700; color: #111; margin-bottom: 16px; }
.itinerary h2 span { font-weight: 500; color: #666; }
.place-row { display: grid; grid-template-columns: 22px auto; align-items: center; gap: 9px; margin-bottom: 18px; }
.place-row:last-child { margin-bottom: 0; }
.place-row input[type="checkbox"] { width: 22px; height: 22px; margin: 0; cursor: default; accent-color: #111; }
.place-card { display: flex; align-items: stretch; border: 1px solid #e8e8e8; border-radius: 6px; min-height: 96px; overflow: hidden; background: #fff; padding-right: 6px; }
.place-photo { width: 96px; height: 96px; object-fit: cover; flex-shrink: 0; clip-path: inset(0 0 0 100% round 0 6px 6px 0); }
.place-copy { display: flex; flex-direction: column; justify-content: center; gap: 4px; padding: 16px 12px 16px 16px; min-width: 0; flex: 1; }
.place-title { font-size: 14px; line-height: 19px; font-weight: 700; color: #111; margin: 0; display: block; word-break: break-word; overflow-wrap: break-word; white-space: normal; }
.place-region, .place-type { font-size: 14px; line-height: 19px; font-weight: 500; color: #666; margin: 0; display: block; word-break: break-word; overflow-wrap: break-word; white-space: normal; }
.place-grip { width: 18px; height: 24px; flex-shrink: 0; align-self: center; margin-left: auto; }
.partial-slot { margin-left: 31px; height: 18px; overflow: hidden; display: block; }
.partial-card { min-height: 96px; border: 1px solid #e8e8e8; border-radius: 6px 6px 0 0; overflow: hidden; display: flex; align-items: center; justify-content: center; }
.partial-card img { width: 96px; height: auto; display: block; }"
}
